package sqlstore

import (
	"crypto/sha256"
	"encoding/binary"
	"encoding/json"
	"fmt"
	"hash"
	"math"
	"regexp"

	"github.com/sean2077/pairroom/internal/model"
)

// The first slice's closed surface. Everything else is refused with a stable
// class rather than simulated.
const (
	namespaceHuman   = "human"
	opKindAppendFact = "append_fact"
	opKindHumanSend  = "human_send"
	// The audit record is generated by the trusted operation, not narrated by
	// the caller: this slice fixes its kind and outcome and forbids free-form
	// detail. Structured diagnostics arrive with a later mutation version.
	auditKindAppendFact  = "fact.append"
	auditOutcomeAccepted = "accepted"

	// mutationVersionV1 is the current mutation codec version. Unknown versions
	// are refused; future versions change this constant and add a new encoding.
	mutationVersionV1 = 1
	// sqlstoreSchemaVersion is the SQL schema version this build applies and
	// accepts. It is independent of the Local store's format window.
	sqlstoreSchemaVersion = 1
	// factCodecVersion versions the stored event encoding. It is independent of
	// the Local Store version (which also covers provisioning and windows).
	factCodecVersion = 1

	maxEncodingBytes = 262144
)

// Stable outcome classes. Callers key recovery behavior on these, never on
// message text.
const (
	ClassUnsupportedNamespace = "unsupported_namespace"
	ClassUnsupportedOp        = "unsupported_op"
	ClassUnsupportedMutation  = "unsupported_mutation"
	ClassInvalidRequest       = "invalid_request"
	ClassInvalidFact          = "invalid_fact"
	ClassAuthorization        = "authorization"
	ClassRoomNotFound         = "room_not_found"
	ClassRevisionConflict     = "revision_conflict"
	ClassPayloadConflict      = "payload_conflict"
	ClassLeaseLost            = "lease_lost"
	ClassStoredFactUnreadable = "stored_fact_unreadable"
	ClassStateInvalid         = "state_invalid"
	ClassDiscoveryRestart     = "discovery_restart_exceeded"
	ClassSerializationFailure = "serialization_failure"
	ClassDeadlockDetected     = "deadlock_detected"
	ClassConstraintViolation  = "constraint_violation"
	ClassStatementFailed      = "statement_failed"
	ClassConnectionFailed     = "connection_failed"
	ClassConnectionException  = "connection_exception"
	ClassCommitUncertain      = "commit_uncertain"
	ClassRangeExceeded        = "range_exceeded"
	ClassOperationBudget      = "operation_budget_exceeded"
	ClassCanceled             = "canceled"
	ClassClosed               = "closed"
)

var (
	schemaNamePattern = regexp.MustCompile(`^[a-z_][a-z0-9_]{0,62}$`)
	factKindPattern   = regexp.MustCompile(`^[a-z][a-z0-9_.-]{0,63}$`)
)

// AuthContext is constructed by the authenticated layer; the kernel never
// parses credentials and never takes identity from the command's own key.
// This slice is human-only: binding/device authority records arrive with a
// later mutation version, so no binding reference is accepted here.
type AuthContext struct {
	Deployment string
	UserID     string
}

// OpKey is the idempotency namespace of §13. The binding fields exist for the
// later slice; this kernel refuses any non-human namespace.
type OpKey struct {
	Namespace  string
	Deployment string
	RoomID     string
	BindingID  string
	Generation uint64
	OpKind     string
	Identifier string
	Principal  string
}

// AuditRecord is the same-transaction audit fact. Detail never carries message
// bodies, tokens or native session identifiers.
type AuditRecord struct {
	Kind    string
	Outcome string
	Detail  string
}

// Mutation is the strictly versioned, complete mutation carrier. There is no
// partial generic intent: the canonical hash below covers every stable field
// of the mutation this slice supports, so a changed body or audit detail can
// never replay under the same key.
//
// Fact is produced by a trusted internal producer (the Room core) from the
// guard-locked revision; this kernel implements no end-user or raw-event
// upload surface, and Fact kinds are opaque to it.
type Mutation struct {
	Version int
	Fact    model.Event
	Audit   AuditRecord
}

// Command is one commit request.
type Command struct {
	Auth AuthContext
	Key  OpKey
	// ExpectedRevision is checked strictly against the locked Room revision.
	// Zero is a legal initial revision; there is no bypass.
	ExpectedRevision uint64
	Mutation         Mutation
}

// Outcome is the transaction-state result.
type Outcome string

const (
	OutcomeCommitted    Outcome = "committed"
	OutcomeReplayed     Outcome = "replayed"
	OutcomeConflict     Outcome = "conflict"
	OutcomeNotCommitted Outcome = "not_committed"
	OutcomeRefused      Outcome = "refused"
	OutcomeUnknown      Outcome = "unknown"
)

// Result carries the outcome and, for committed/replayed outcomes, the durable
// fact. Replayed returns the original stored fact (original event id and
// creation time) — never a freshly constructed candidate event.
type Result struct {
	Outcome  Outcome
	Class    string
	Err      error
	Seq      uint64
	Revision uint64
	Fact     model.Event
}

// KernelError is the error form of a non-committed outcome.
type KernelError struct {
	Outcome Outcome
	Class   string
	Err     error
}

func (e *KernelError) Error() string {
	if e.Err != nil {
		return fmt.Sprintf("sqlstore %s (%s): %v", e.Outcome, e.Class, e.Err)
	}
	return fmt.Sprintf("sqlstore %s (%s)", e.Outcome, e.Class)
}

func (e *KernelError) Unwrap() error { return e.Err }

func refused(class string, cause error) (Result, error) {
	err := &KernelError{Outcome: OutcomeRefused, Class: class, Err: cause}
	return Result{Outcome: OutcomeRefused, Class: class, Err: err}, err
}

func notCommitted(class string, cause error) (Result, error) {
	err := &KernelError{Outcome: OutcomeNotCommitted, Class: class, Err: cause}
	return Result{Outcome: OutcomeNotCommitted, Class: class, Err: err}, err
}

func unknown(class string, cause error) (Result, error) {
	err := &KernelError{Outcome: OutcomeUnknown, Class: class, Err: cause}
	return Result{Outcome: OutcomeUnknown, Class: class, Err: err}, err
}

// validateCommand performs the admission checks that need no database access.
// An empty class means the command may proceed.
func validateCommand(cmd Command) string {
	switch {
	case cmd.Key.Namespace != namespaceHuman:
		return ClassUnsupportedNamespace
	case cmd.Key.OpKind != opKindAppendFact:
		return ClassUnsupportedOp
	case cmd.Mutation.Version != mutationVersionV1:
		return ClassUnsupportedMutation
	case cmd.Key.BindingID != "" || cmd.Key.Generation != 0:
		return ClassUnsupportedNamespace
	case cmd.Auth.Deployment == "" || cmd.Key.Deployment != cmd.Auth.Deployment:
		return ClassInvalidRequest
	case cmd.Auth.UserID == "" || cmd.Key.Principal != cmd.Auth.UserID:
		return ClassInvalidRequest
	case cmd.Key.RoomID == "" || cmd.Key.Identifier == "":
		return ClassInvalidRequest
	case cmd.ExpectedRevision > math.MaxInt64:
		return ClassInvalidRequest
	case cmd.Mutation.Fact.RoomID != cmd.Key.RoomID:
		return ClassInvalidFact
	case cmd.Mutation.Fact.ID == "" || !factKindPattern.MatchString(cmd.Mutation.Fact.Kind):
		return ClassInvalidFact
	case cmd.Mutation.Fact.Actor != model.ActorUser:
		return ClassInvalidFact
	case len(cmd.Mutation.Fact.Data) == 0 || !json.Valid(cmd.Mutation.Fact.Data):
		return ClassInvalidFact
	case cmd.Mutation.Audit.Kind != auditKindAppendFact || cmd.Mutation.Audit.Outcome != auditOutcomeAccepted:
		return ClassInvalidFact
	case cmd.Mutation.Audit.Detail != "":
		return ClassInvalidFact
	}
	return ""
}

// canonicalHash covers the complete stable mutation: the full operation key,
// the mutation version, the fact's room, kind, actor and exact data bytes, and
// the audit kind/outcome/detail. Excluded are only system-generated artifacts —
// the event id, assigned sequence and creation time, and the audit/commit
// bookkeeping — so an identical logical operation hashes identically while any
// changed stable field can never replay under the same key.
func canonicalHash(key OpKey, mutation Mutation) [32]byte {
	h := sha256.New()
	writePart(h, []byte("sqlstore.mutation.v1"))
	writePart(h, []byte(key.Namespace))
	writePart(h, []byte(key.Deployment))
	writePart(h, []byte(key.RoomID))
	writePart(h, []byte(key.BindingID))
	var generation [8]byte
	binary.BigEndian.PutUint64(generation[:], key.Generation)
	h.Write(generation[:])
	writePart(h, []byte(key.OpKind))
	writePart(h, []byte(key.Identifier))
	writePart(h, []byte(key.Principal))
	var version [8]byte
	binary.BigEndian.PutUint64(version[:], uint64(mutation.Version))
	h.Write(version[:])
	writePart(h, []byte(mutation.Fact.RoomID))
	writePart(h, []byte(mutation.Fact.Kind))
	writePart(h, []byte(mutation.Fact.Actor))
	writePart(h, mutation.Fact.Data)
	writePart(h, []byte(mutation.Audit.Kind))
	writePart(h, []byte(mutation.Audit.Outcome))
	writePart(h, []byte(mutation.Audit.Detail))
	var sum [32]byte
	copy(sum[:], h.Sum(nil))
	return sum
}

func writePart(h hash.Hash, part []byte) {
	var size [8]byte
	binary.BigEndian.PutUint64(size[:], uint64(len(part)))
	h.Write(size[:])
	h.Write(part)
}
